// Day-by-day / stage-by-stage breakdowns of the major Maithil rituals, used by
// the RitualStages interactive component on the ritual detail pages.
// Researched from multiple sources (Wikipedia, Maithil-culture sites, news features).
// `key` -> stage image at /img/stage-<ritualSlug>-<key>.jpg (generated by
// scripts/gen-stage-images.mjs via Pollinations; component falls back gracefully).

export interface RitualStage {
  key: string;
  label: string; // short tab label
  title: string;
  body: string; // overview — supports \n\n paragraphs and **bold**/*italic*
  vidhi?: string[]; // the rite, step by step (ordered procedure)
  objects?: string; // things utilised — "·"-separated, shown as labelled chips
  songs?: { name: string; note: string }[]; // folk songs sung at this stage
  variation?: string; // regional / community variation note
  symbols?: string; // key meanings/symbols, "·"-separated chips (legacy field)
  prompt?: string; // image-generation prompt
  mantra?: { sanskrit: string; translit: string; meaning: string };
  context?: boolean; // a "background" tab (origins/why/today) rather than a step
}

const M = 'Authentic Mithila Madhubani folk-art painting, intricate double-line work, natural earthy pigments, ornamental border, flat figures, no text';

